27  @WebServlet(value = "/sqli-00/BenchmarkTest00200")
28  public class BenchmarkTest00200 extends HttpServlet {
30      private static final long serialVersionUID = 1L;
32      @Override
33      public void doGet(HttpServletRequest request, HttpServletResponse response)
34              throws ServletException, IOException {
35          doPost(request, response);
36      }
38      @Override
39      public void doPost(HttpServletRequest request, HttpServletResponse response)
40              throws ServletException, IOException {
41          response.setContentType("text/html;charset=UTF-8");
43          String param = "";
44          if (request.getHeader("BenchmarkTest00200") != null) {
45              param = request.getHeader("BenchmarkTest00200");
46          }
48          // URL Decode the header value since req.getHeader() doesn't. Unlike req.getParameter().
49          param = java.net.URLDecoder.decode(param, "UTF-8");
51          String bar = "alsosafe";
52          if (param != null) {
53              java.util.List<String> valuesList = new java.util.ArrayList<String>();
54              valuesList.add("safe");
55              valuesList.add(param);
56              valuesList.add("moresafe");
58              valuesList.remove(0); // remove the 1st safe value
60              bar = valuesList.get(1); // get the last 'safe' value
61          }
63          try {
64              String sql = "SELECT * from USERS where USERNAME='foo' and PASSWORD='" + bar + "'";
66              org.owasp.benchmark.helpers.DatabaseHelper.JDBCtemplate.batchUpdate(sql);
67              response.getWriter()
68                      .println(
69                              "No results can be displayed for query: "
70                                      + org.owasp.esapi.ESAPI.encoder().encodeForHTML(sql)
71                                      + "<br>"
72                                      + " because the Spring batchUpdate method doesn't return results.");
73          } catch (org.springframework.dao.DataAccessException e) {
74              if (org.owasp.benchmark.helpers.DatabaseHelper.hideSQLErrors) {
75                  response.getWriter().println("Error processing request.");
76              } else throw new ServletException(e);
77          }
78      }
79  }
